let currentLang = 'en';
function t(key, ...args) {
  let str = LANGS[currentLang][key] || LANGS['en'][key] || key;
  args.forEach(a => str = str.replace('%s', a));
  return str;
}

// 
// LANGUAGE SWITCHING
// 
function toggleLanguage() {
  currentLang = currentLang === 'en' ? 'fr' : 'en';
  applyLanguage();
}

function applyLanguage() {
  // 1. Toggle button
  document.getElementById('lang-flag').textContent = currentLang === 'en' ? '' : '';
  document.getElementById('lang-label').textContent = currentLang === 'en' ? 'FR' : 'EN';

  // 2. All static data-i18n nodes
  document.querySelectorAll('[data-i18n]').forEach(el => {
    const val = LANGS[currentLang][el.getAttribute('data-i18n')];
    if (val !== undefined) el.textContent = val;
  });

  // 3. Dynamic window content (innerHTML-based, must use t() directly)
  renderAbout();
  renderPortfolio();
  renderResume();
  renderContact();
  renderRecycle();
  renderMyComputer();
  renderIE();
  
  initWallpaperPicker();

  // 4. ID-based chrome for calculator, wallpaper, guestbook windows
  //    (these have no data-i18n - updated explicitly to avoid any timing issue)
  renderCalculatorTitle();
  renderWallpaperTitle();
  renderAboutOsTitle();
  renderTerminalTitle();

  // 5. Taskbar app button labels
  updateTaskbar();
}


// Re-applies i18n to the calculator window title/menus (buttons are language-neutral)
function renderCalculatorTitle() {
  const title = document.getElementById('calc-title-text');
  if (title) title.textContent = t('title_calc');
  const menubar = document.getElementById('calc-menubar');
  if (menubar) {
    const items = menubar.querySelectorAll('.menu-item');
    const labels = [t('menu_edit'), t('menu_view'), t('menu_help')];
    items.forEach((el, i) => { if (labels[i]) el.textContent = labels[i]; });
  }
}

function renderWallpaperTitle() {
  const title = document.getElementById('wp-title-text');
  if (title) title.textContent = t('title_wallpaper');
  const choose = document.getElementById('wp-choose-lbl');
  if (choose) choose.textContent = t('wp_choose');
  const apply = document.getElementById('wp-apply-btn');
  if (apply) apply.textContent = t('wp_apply');
  const cancel = document.getElementById('wp-cancel-btn');
  if (cancel) cancel.textContent = t('wp_cancel');
  const status = document.getElementById('wp-status');
  if (status && !status._customText) status.textContent = t('wp_status');
}


// 
// DYNAMIC WINDOW RENDERERS
// 
function renderAbout() {
  const isEN = currentLang === 'en';
  const separator = `+--------------------------------------------------+`;

  const enContent = `
${separator}
  FILE: about.txt         ENCODING: UTF-8
  AUTHOR: Yanis Gallouze  VERSION: 1.6
${separator}

  Hi, I'm Yanis!

  Welcome to yanyanOS -- my portfolio, but turned into a
  Windows 95-style desktop. I'm Yanis Gallouze, a third-year
  Computer Science student at the Universite de la
  Nouvelle-Caledonie, mostly into cybersecurity, networks,
  and embedded systems.

${separator}
  ABOUT THIS SITE
${separator}

  Instead of making a normal boring portfolio, I turned it
  into a fake desktop where you can open apps and explore.
  Most of it was built with Claude AI -- I only helped
  debugging things that did not work properly because
  honestly I just like messing around with AI and seeing
  what cool things I can make with it.
  I\'m not really a hardcore dev, feel free to suggest me
  things to add/change and feel free to use my work here
  for you own portfolio.

  Click around, open the apps, check my projects, my CV,
  or just explore yanyanOS. It's my portfolio... as a
  tiny OS.

${separator}
  MORE FEATURES & UPDATES COMING TO yanyanOS...
${separator}`;

  const frContent = `
${separator}
  FICHIER: about.txt      ENCODAGE: UTF-8
  AUTEUR: Yanis Gallouze  VERSION: 1.6
${separator}

  Bonjour, je suis Yanis !

  Bienvenue sur yanyanOS -- mon portfolio personnel,
  reimagine comme un bureau Windows 95. Je suis Yanis
  Gallouze, etudiant en 3eme annee de Licence Informatique
  a l'Universite de la Nouvelle-Caledonie, passionne par
  la cybersecurite, les reseaux et les systemes embarques.

${separator}
  A PROPOS DU SITE
${separator}

  Au lieu de faire un portfolio classique et ennuyeux, je
  l'ai transforme en faux bureau. La majorite a ete
  construite avec Claude AI -- moi j\'ai surtout corrigé
  les bugs quand certains trucs ne marchaient pas, parce
  que pour être honnête j\'aime bien jouer avec l\'IA et 
  voir les trucs cool qu\'on peut construire avec.

  Je ne suis pas vraiment un gros développeur hardcore, 
  donc si vous avez des idées de choses à ajouter
  ou à changer, n/hésitez pas. Et si ça peut vous servir
  pour votre propre portfolio, prenez ce que vous voulez.

  Cliquez sur le bureau, ouvrez les apps, consultez mes
  projets, mon CV, ou explorez juste yanyanOS.

${separator}
  PLUS DE FONCTIONNALITES & MISES A JOUR A VENIR...
${separator}`;

  const content = isEN ? enContent : frContent;
  document.getElementById('about-content').innerHTML =
    `<textarea id="about-notepad-area" readonly spellcheck="false">${content}</textarea>`;
}


