function updateClock() {
  const now = new Date();
  let h = now.getHours(), m = now.getMinutes();
  const ampm = h >= 12 ? 'PM' : 'AM';
  h = h%12||12;
  document.getElementById('taskbar-clock').textContent = `${h}:${m.toString().padStart(2,'0')} ${ampm}`;
}
