// 
// SCREENSAVER
// 
let ssTimer = null, ssActive = false, ssAnimFrame = null;
const SS_DELAY = 60000; // 60 seconds idle

function resetSsTimer() {
  if (ssActive) return;
  clearTimeout(ssTimer);
  ssTimer = setTimeout(launchScreensaver, SS_DELAY);
}

document.addEventListener('mousemove', resetSsTimer);
document.addEventListener('keydown',   resetSsTimer);
document.addEventListener('click',     resetSsTimer);
resetSsTimer();

function launchScreensaver() {
  if (document.getElementById('dialog-overlay').style.display === 'flex') return;
  ssActive = true;
  const ss = document.getElementById('screensaver');
  ss.classList.add('active');
  startSsAnimation();
}

function dismissScreensaver() {
  if (!ssActive) return;
  ssActive = false;
  document.getElementById('screensaver').classList.remove('active');
  cancelAnimationFrame(ssAnimFrame);
  resetSsTimer();
}

function startSsAnimation() {
  const canvas = document.getElementById('ss-canvas');
  canvas.width  = window.innerWidth;
  canvas.height = window.innerHeight;
  const ctx = canvas.getContext('2d');

  // Single bouncing DVD-style "yanyanOS" logo
  ctx.font = 'bold 48px VT323, monospace';
  const textW = ctx.measureText('yanyanOS').width;
  const textH = 48;
  const logo = {
    x: Math.random() * (canvas.width - textW),
    y: textH + Math.random() * (canvas.height - textH * 2),
    vx: (Math.random() > 0.5 ? 1 : -1) * 2,
    vy: (Math.random() > 0.5 ? 1 : -1) * 2,
    color: `hsl(${Math.random()*360},80%,65%)`
  };

  function frame() {
    if (!ssActive) return;
    ctx.fillStyle = '#000';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    logo.x += logo.vx;
    logo.y += logo.vy;
    if (logo.x <= 0 || logo.x + textW >= canvas.width)  { logo.vx *= -1; logo.color = `hsl(${Math.random()*360},80%,65%)`; }
    if (logo.y - textH <= 0 || logo.y >= canvas.height)  { logo.vy *= -1; logo.color = `hsl(${Math.random()*360},80%,65%)`; }

    ctx.font = 'bold 48px VT323, monospace';
    ctx.fillStyle = logo.color;
    ctx.shadowColor = logo.color;
    ctx.shadowBlur = 18;
    ctx.fillText('yanyanOS', logo.x, logo.y);
    ctx.shadowBlur = 0;

    ssAnimFrame = requestAnimationFrame(frame);
  }

  ctx.fillStyle = '#000';
  ctx.fillRect(0, 0, canvas.width, canvas.height);
  ssAnimFrame = requestAnimationFrame(frame);
}

// 
// WINDOW SNAP (drag to edge)
// 
let snapPreview = null;
function getSnapPreviewEl() {
  if (!snapPreview) {
    snapPreview = document.createElement('div');
    snapPreview.style.cssText = 'position:fixed;background:rgba(0,0,128,.25);border:2px solid rgba(0,0,128,.6);pointer-events:none;z-index:9990;display:none;transition:all .1s';
    document.body.appendChild(snapPreview);
  }
  return snapPreview;
}

function getSnapZone(x, y) {
  const W = window.innerWidth, H = window.innerHeight - 36, edge = 20;
  if (x < edge) return 'left';
  if (x > W - edge) return 'right';
  if (y < edge) return 'top';
  return null;
}

function showSnapPreview(zone) {
  const el = getSnapPreviewEl();
  const W = window.innerWidth, H = window.innerHeight - 36;
  const zones = {
    left:  {left:'0',   top:'0',   width:'50%',  height: H+'px'},
    right: {left:'50%', top:'0',   width:'50%',  height: H+'px'},
    top:   {left:'0',   top:'0',   width:'100%', height: H+'px'},
  };
  if (!zones[zone]) { el.style.display='none'; return; }
  Object.assign(el.style, zones[zone], {display:'block'});
}

function applySnap(zone, el) {
  const W = window.innerWidth, H = window.innerHeight - 36;
  const snaps = {
    left:  {left:'0',   top:'0', width: Math.floor(W/2)+'px', height: H+'px'},
    right: {left: Math.floor(W/2)+'px', top:'0', width: Math.floor(W/2)+'px', height: H+'px'},
    top:   {left:'0',   top:'0', width: W+'px', height: H+'px'},
  };
  if (!snaps[zone]) return;
  Object.assign(el.style, snaps[zone]);
}

// Snap logic is hooked into the existing drag listeners below via snapCheck()
function snapCheck(e, releasing) {
  if (!dragState) { getSnapPreviewEl().style.display = 'none'; return; }
  const zone = getSnapZone(e.clientX, e.clientY);
  if (releasing) {
    getSnapPreviewEl().style.display = 'none';
    if (zone) applySnap(zone, dragState.el);
  } else {
    showSnapPreview(zone);
  }
}



// 
// TERMINAL - yanyanSH
// 
let termHistory   = [];   // command history
let termHistIdx   = -1;   // history navigation index
let termInitialized = false;
let termCwd       = '~';

function renderTerminalTitle() {
  const el = document.getElementById('term-title-text');
  if (el) el.textContent = t('title_terminal');
}

function initTerminal() {
  if (termInitialized) {
    focusTermInput(); return;
  }
  termInitialized = true;
  termPrint('ascii', [
    ' __   __  ___  __   _  __   __  ___  __  _  _ ',
    ' \\ \\ / / / _ \\ \\ \\ | | \\ \\ / / / _ \\|  \\| |',
    '  \\ V / | (_) | \\ \\| |  \\ V / | (_) | | \\ |',
    '   |_|   \\__\\_\\  \\___|   |_|   \\___/|_|\\__|',
  ].join('\n'));
  termPrint('info', 'yanyanSH v1.6 - Type "help" to see available commands.');
  termPrint('warn', 'WARNING: This terminal is completely fake. But the sass is real.');
  termNewLine();
  focusTermInput();
}

function focusTermInput() {
  const inp = document.getElementById('term-input');
  if (inp) setTimeout(() => inp.focus(), 50);
}

function termNewLine() {
  termPrint('out', '');
}

function termPrint(cls, text) {
  const out = document.getElementById('term-output');
  if (!out) return;
  const div = document.createElement('div');
  div.className = 't-line t-' + cls;
  div.innerHTML = text
    .replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;')
    .replace(/\[b\](.*?)\[\/b\]/g, '<strong>$1</strong>')
    .replace(/\[c:(.*?)\](.*?)\[\/c\]/g, '<span style="color:$1">$2</span>');
  out.appendChild(div);
  out.scrollTop = out.scrollHeight;
}

function termPrintRaw(html) {
  const out = document.getElementById('term-output');
  if (!out) return;
  const div = document.createElement('div');
  div.className = 't-line';
  div.innerHTML = html;
  out.appendChild(div);
  out.scrollTop = out.scrollHeight;
}

function termKeyDown(e) {
  const inp = e.target;
  if (e.key === 'Enter') {
    const cmd = inp.value.trim();
    inp.value = '';
    termHistIdx = -1;
    if (cmd) { termHistory.unshift(cmd); if (termHistory.length > 50) termHistory.pop(); }
    // Echo the command
    termPrint('prompt', `yanyan@yanyanOS:${termCwd}$ [b]${cmd}[/b]`);
    if (cmd) runTermCmd(cmd);
    else termNewLine();
  } else if (e.key === 'ArrowUp') {
    e.preventDefault();
    if (termHistIdx < termHistory.length - 1) {
      termHistIdx++;
      inp.value = termHistory[termHistIdx];
      setTimeout(() => inp.setSelectionRange(inp.value.length, inp.value.length), 0);
    }
  } else if (e.key === 'ArrowDown') {
    e.preventDefault();
    if (termHistIdx > 0) { termHistIdx--; inp.value = termHistory[termHistIdx]; }
    else { termHistIdx = -1; inp.value = ''; }
  } else if (e.key === 'l' && e.ctrlKey) {
    e.preventDefault();
    document.getElementById('term-output').innerHTML = '';
  }
}

//  Command dispatcher 
function runTermCmd(raw) {
  const parts = raw.trim().split(/\s+/);
  const cmd   = parts[0].toLowerCase();
  const args  = parts.slice(1);

  const commands = {
    help, clear, ls, pwd, cd, whoami, uname, date: cmdDate,
    echo: cmdEcho, cat, sudo, rm, mkdir, touch, ps, top: cmdTop,
    man, fortune, sl, yes, lolcat, neofetch, history: cmdHistory,
    exit: cmdExit, reboot: cmdReboot, shutdown: cmdShutdown,
    'git': cmdGit, npm: cmdNpm, python: cmdPython, python3: cmdPython,
    ping, curl, wget, ssh, vim, nano, emacs,
    'cd ..': () => cd(['..'])
  };

  if (commands[cmd]) {
    commands[cmd](args);
  } else {
    termPrint('err', `bash: ${cmd}: command not found`);
    termPrint('out', `Did you mean one of these? Try "help" for the full list.`);
  }
  termNewLine();
}

//  Individual commands 
