// 
// STICKY NOTES - full app
// 
let stickyCounter = 0;
let stickyNotes   = []; // {id, text, color, pos}

const stickyColors = {
  yellow: {bg:'#ffff88', header:'#e6c800', text:'#555500'},
  pink:   {bg:'#ffccee', header:'#e090c0', text:'#660044'},
  blue:   {bg:'#cce8ff', header:'#88bbdd', text:'#003366'},
  green:  {bg:'#ccffcc', header:'#88cc88', text:'#004400'},
  orange: {bg:'#ffe0aa', header:'#dd9933', text:'#553300'},
};
let activeStickyDrag = null;

function newStickyFromApp() {
  const id = 'sticky-' + (++stickyCounter);
  const colorKeys = Object.keys(stickyColors);
  const color = colorKeys[stickyCounter % colorKeys.length];
  stickyNotes.push({id, text:'', color, createdAt: new Date().toLocaleString()});
  renderStickyApp();
  spawnStickyOnDesktop(id, '', color, null);
}

function renderStickyApp() {
  const list = document.getElementById('stickies-list');
  const empty = document.getElementById('stickies-empty');
  const count = document.getElementById('stickies-count');
  if (!list) return;

  // Remove old note rows (keep the empty msg)
  list.querySelectorAll('.sticky-app-row').forEach(el => el.remove());

  if (!stickyNotes.length) {
    if (empty) empty.style.display = '';
    if (count) count.textContent = '0 notes';
    return;
  }
  if (empty) empty.style.display = 'none';
  if (count) count.textContent = stickyNotes.length + (stickyNotes.length === 1 ? ' note' : ' notes');

  stickyNotes.forEach(note => {
    const c = stickyColors[note.color] || stickyColors.yellow;
    const row = document.createElement('div');
    row.className = 'sticky-app-row';
    row.dataset.id = note.id;
    row.style.cssText = `background:${c.bg};border-left:4px solid ${c.header};padding:6px 8px;font-size:11px;cursor:pointer;display:flex;justify-content:space-between;align-items:flex-start;gap:6px;border-bottom:1px solid rgba(0,0,0,.1)`;

    const preview = note.text ? note.text.slice(0,60).replace(/\n/g,' ') + (note.text.length>60?'…':'') : '(empty note)';
    row.innerHTML = `
      <div style="flex:1;overflow:hidden">
        <div style="font-weight:bold;color:${c.text};font-family:'Comic Sans MS',cursive">${preview}</div>
        <div style="font-size:9px;color:#999;margin-top:2px">${note.createdAt}</div>
      </div>
      <div style="display:flex;gap:3px;flex-shrink:0">
        <button class="win95-btn" style="font-size:9px;padding:1px 4px" onclick="focusStickyOnDesktop('${note.id}')">📌</button>
        <button class="win95-btn" style="font-size:9px;padding:1px 4px" onclick="deleteStickyNote('${note.id}')">✕</button>
      </div>`;

    // Click to focus on desktop
    row.querySelector('div').addEventListener('click', () => focusStickyOnDesktop(note.id));
    list.appendChild(row);
  });
}

function spawnStickyOnDesktop(id, text, color, pos) {
  const c = stickyColors[color] || stickyColors.yellow;
  const colorKeys = Object.keys(stickyColors);
  const desk = document.getElementById('desktop');
  const x = pos ? pos.x : 80  + Math.random() * 400;
  const y = pos ? pos.y : 60  + Math.random() * 250;

  // Remove if already exists
  const existing = document.getElementById('sticky-desktop-' + id);
  if (existing) existing.remove();

  const note = document.createElement('div');
  note.className = 'sticky-note';
  note.id = 'sticky-desktop-' + id;
  note.style.cssText = `left:${x}px;top:${y}px;background:${c.bg};z-index:5`;

  note.innerHTML = `
    <div class="sticky-header" style="background:${c.header}" onmousedown="startStickyDrag(event,'sticky-desktop-${id}')">
      <div class="sticky-colors">
        ${colorKeys.map(col =>
          `<div class="sticky-color-dot" style="background:${stickyColors[col].bg};border:2px solid ${col===color?'#333':'transparent'}"
           onclick="changeStickyColor('${id}','${col}')"></div>`
        ).join('')}
      </div>
      <div style="font-size:9px;color:rgba(0,0,0,.5);flex:1;text-align:center;pointer-events:none">📌</div>
      <div class="sticky-close" style="margin-right:2px" onclick="deleteStickyNote('${id}')" title="Delete">🗑</div>
      <div class="sticky-close" onclick="hideStickyOnDesktop('${id}')" title="Close">✕</div>
    </div>
    <textarea class="sticky-body" style="background:${c.bg};color:${c.text}"
      placeholder="Type your note..."
      oninput="syncStickyText('${id}',this.value)">${text}</textarea>
    <div class="sticky-footer" style="color:${c.text}88">Sticky Notes</div>`;

  note.addEventListener('mousedown', () => {
    document.querySelectorAll('.sticky-note').forEach(n => n.style.zIndex='5');
    note.style.zIndex = '9';
  });

  desk.appendChild(note);
  note.querySelector('textarea').focus();
}

function syncStickyText(id, val) {
  const note = stickyNotes.find(n => n.id === id);
  if (note) { note.text = val; renderStickyApp(); }
}

function focusStickyOnDesktop(id) {
  const el = document.getElementById('sticky-desktop-' + id);
  if (el) {
    el.style.display = '';
    document.querySelectorAll('.sticky-note').forEach(n => n.style.zIndex='5');
    el.style.zIndex = '9';
    el.querySelector('textarea') && el.querySelector('textarea').focus();
  } else {
    // Respawn if it was closed
    const note = stickyNotes.find(n => n.id === id);
    if (note) spawnStickyOnDesktop(id, note.text, note.color, null);
  }
}

function hideStickyOnDesktop(id) {
  const el = document.getElementById('sticky-desktop-' + id);
  if (el) el.style.display = 'none';
}

function deleteStickyNote(id) {
  stickyNotes = stickyNotes.filter(n => n.id !== id);
  const el = document.getElementById('sticky-desktop-' + id);
  if (el) el.remove();
  renderStickyApp();
}

function clearAllStickies() {
  stickyNotes.forEach(n => {
    const el = document.getElementById('sticky-desktop-' + n.id);
    if (el) el.remove();
  });
  stickyNotes = [];
  renderStickyApp();
}

function changeStickyColor(id, color) {
  const note = stickyNotes.find(n => n.id === id);
  if (note) note.color = color;
  const c  = stickyColors[color];
  const el = document.getElementById('sticky-desktop-' + id);
  if (!el || !c) return;
  el.style.background = c.bg;
  el.querySelector('.sticky-header').style.background = c.header;
  el.querySelector('.sticky-body').style.background   = c.bg;
  el.querySelector('.sticky-body').style.color        = c.text;
  el.querySelector('.sticky-footer').style.color      = c.text + '88';
  // Update dot borders
  el.querySelectorAll('.sticky-color-dot').forEach((dot,i) => {
    const cols = Object.keys(stickyColors);
    dot.style.border = `2px solid ${cols[i]===color?'#333':'transparent'}`;
  });
  renderStickyApp();
}

function startStickyDrag(e, elId) {
  if (e.target.classList.contains('sticky-close') ||
      e.target.classList.contains('sticky-color-dot')) return;
  const el = document.getElementById(elId);
  if (!el) return;
  activeStickyDrag = {el, startX: e.clientX - el.offsetLeft, startY: e.clientY - el.offsetTop};
  e.preventDefault();
}

document.addEventListener('mousemove', e => {
  if (!activeStickyDrag) return;
  const {el,startX,startY} = activeStickyDrag;
  el.style.left = Math.max(0, e.clientX - startX) + 'px';
  el.style.top  = Math.max(0, Math.min(window.innerHeight - 72, e.clientY - startY)) + 'px';
});
document.addEventListener('mouseup', () => activeStickyDrag = null);

function initStickyNotes() {
  // Spawn two fun preloaded notes
  const id1 = 'sticky-' + (++stickyCounter);
  const id2 = 'sticky-' + (++stickyCounter);
  const t1  = " TODO:\n- Ship portfolio\n- Touch grass\n- Reply to recruiters (lol)\n- More coffee";
  const t2  = " Reminder:\nYou are doing great!\n\n- The cat";
  stickyNotes.push({id:id1, text:t1, color:'yellow', createdAt: new Date().toLocaleString()});
  stickyNotes.push({id:id2, text:t2, color:'pink',   createdAt: new Date().toLocaleString()});
  spawnStickyOnDesktop(id1, t1, 'yellow', {x:120, y:160});
  spawnStickyOnDesktop(id2, t2, 'pink',   {x:320, y:210});
  renderStickyApp();
}

