function playYouveGotMail() {
  try {
    const ctx = new (window.AudioContext || window.webkitAudioContext)();
    // Cheerful 3-note ding melody: E5 G5 C6
    const notes = [{f:659,t:0,d:.12},{f:784,t:.13,d:.12},{f:1047,t:.27,d:.22}];
    notes.forEach(({f,t,d}) => {
      const o = ctx.createOscillator();
      const g = ctx.createGain();
      o.connect(g); g.connect(ctx.destination);
      o.type = 'sine'; o.frequency.value = f;
      const start = ctx.currentTime + t;
      g.gain.setValueAtTime(0, start);
      g.gain.linearRampToValueAtTime(0.18, start + 0.01);
      g.gain.exponentialRampToValueAtTime(0.001, start + d);
      o.start(start); o.stop(start + d + 0.05);
    });
  } catch(e) {}
}

function showNotification(opts) {
  // opts: { icon, sender, msg, duration }
  if (opts.sound !== false) playYouveGotMail();
  const container = document.getElementById('notif-container');
  const toast = document.createElement('div');
  toast.className = 'notif-toast';
  const dur = opts.duration || 15000;
  toast.innerHTML = `
    <div class="notif-titlebar">
      <span class="notif-icon">${opts.icon || ''}</span>
      <span style="flex:1;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${opts.title || 'New Message'}</span>
      <div class="notif-close" onclick="dismissToast(this.closest('.notif-toast'))">✕</div>
    </div>
    <div class="notif-body">
      <div class="notif-sender">${opts.sender || ''}</div>
      <div>${opts.msg.replace(/\n/g,'<br>')}</div>
    </div>
    <div class="notif-progress" style="animation-duration:${dur}ms"></div>`;

  container.appendChild(toast);

  // Pulse tray dot
  const dot = document.getElementById('tray-notif-dot');
  dot.style.display = 'block';

  // Auto-dismiss
  const tid = setTimeout(() => dismissToast(toast), dur);
  toast._tid = tid;
}

function dismissToast(toast) {
  if (!toast || toast._dismissed) return;
  toast._dismissed = true;
  clearTimeout(toast._tid);
  toast.classList.add('hiding');
  setTimeout(() => {
    toast.remove();
    // Hide tray dot if no more toasts
    if (!document.getElementById('notif-container').children.length) {
      document.getElementById('tray-notif-dot').style.display = 'none';
    }
  }, 320);
}

